function inside(p,r){let c=false;for(let i=0,j=r.length-1;i<r.length;j=i++)if(((r[i][1]>p[1])!==(r[j][1]>p[1]))&&(p[0]<(r[j][0]-r[i][0])*(p[1]-r[i][1])/(r[j][1]-r[i][1])+r[i][0]))c=!c;return c;}
