function applyMaterials(){if(!root)return;root.traverse(n=>{if(!n.isMesh||!n.userData.material)return;const base=n.userData.material;let p=n;while(p&&!groups.has(p.userData.id))p=p.parent;const chosen=p?.userData.id===state.selected||Boolean(state.selectedAssemblyId&&p?.userData.joinedAssemblyId===state.selectedAssemblyId);n.material.color.copy(base.color);if(n.material.emissive&&base.emissive){n.material.emissive.copy(base.emissive);n.material.emissiveIntensity=base.emissiveIntensity;}if(state.white){n.material.color.set(n.name.includes('window')?'#8a9b97':'#e5e2d4');n.material.emissive?.set('#000000');}if(state.night&&(n.name.includes('window')||n.name.includes('glazing'))&&n.material.emissive){n.material.emissive.set('#d3ad61');n.material.emissiveIntensity=.45;}if(chosen){n.material.color.lerp(new THREE.Color('#82b68a'),.08);}});if(treeGroup)treeGroup.visible=state.trees;if(waterGroup)waterGroup.visible=state.water;}
function updateModes(){$('#walk').classList.toggle('active',state.mode==='walk');$('#tour').classList.toggle('active',state.tour);$('#overview').classList.toggle('active',state.mode==='orbit'&&!state.tour);$('#mode-hint').textContent=state.mode==='walk'?'WASD / 方向按钮移动 · 拖动转头 · Esc 返回鸟瞰':'拖动旋转 · 滚轮缩放 · 点击建筑查看';}
function enterWalk(){state.tour=false;targetMove=null;state.mode='walk';controls.enabled=false;const b=data.buildings.find(b=>b.id===state.selected);let p=b?[b.position[0],b.position[1]+b.lengthApprox*.7+8]:[-30,305];if(!canWalk(...p))p=[-30,305];camera.position.set(p[0],1.78,p[1]);walkYaw=0;walkPitch=0;camera.lookAt(p[0],1.78,p[1]-10);document.body.classList.add('walking');resize();updateModes();toast('拖动转头，使用WASD在校园中移动');}
function exitWalk(reset=true){if(state.mode!=='walk')return;state.mode='orbit';document.body.classList.remove('walking');controls.enabled=true;resize();if(reset)overview();updateModes();}
function drawMap(){if(!data)return;const c=$('#minimap'),ctx=c.getContext('2d'),w=c.width,h=c.height,b=data.bounds,pad=7,s=Math.min((w-pad*2)/b.width,(h-pad*2)/b.depth),ox=(w-b.width*s)/2,oz=(h-b.depth*s)/2;const xy=p=>[ox+(p[0]-b.minX)*s,oz+(p[1]-b.minZ)*s];ctx.clearRect(0,0,w,h);ctx.lineCap='round';for(const r of data.waterway){ctx.beginPath();r.points.map(xy).forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.lineWidth=2;ctx.strokeStyle='#9cbfba';ctx.stroke();}for(const r of data.roads){ctx.beginPath();r.points.map(xy).forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.lineWidth=.7;ctx.strokeStyle='#d4dfcb';ctx.stroke();}for(const b of data.buildings){ctx.beginPath();b.rings[0].map(xy).forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fillStyle=state.selected===b.id?'#365e3f':'#a4b293';ctx.fill();}const q=xy([controls.target.x,controls.target.z]);ctx.strokeStyle='#527b59';ctx.lineWidth=1;ctx.beginPath();ctx.arc(...q,4,0,Math.PI*2);ctx.stroke();c.onclick=e=>{const rect=c.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*w,y=(e.clientY-rect.top)/rect.height*h,p=[(x-ox)/s+b.minX,(y-oz)/s+b.minZ];const near=[...data.buildings].sort((a,b)=>Math.hypot(a.position[0]-p[0],a.position[1]-p[1])-Math.hypot(b.position[0]-p[0],b.position[1]-p[1]))[0];select(near.id,true);};}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),60000);}
function bind(){$('#water-toggle').onchange=e=>{state.water=e.target.checked;applyMaterials();};$('#satellite-open').onclick=()=>showSatellite();$('#satellite-close').onclick=()=>$('#satellite-dialog').close();$('#satellite-overlay-toggle').onchange=e=>{const g=$('#satellite-map #survey-overlay');if(g)g.style.display=e.target.checked?'':'none';};$('#quality').onclick=()=>requestDetail();$$('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();keys.add(b.dataset.key);b.setPointerCapture(e.pointerId);};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.key);});window.addEventListener('resize',resize);$('#search').oninput=renderList;$$('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderList();});$$('[data-preset]').forEach(e=>e.onclick=()=>{if(e.dataset.preset==='parking'){const park=data.roadNetwork.hardscapeAreas.find(a=>a.id==='P02'),stalls=data.roadNetwork.parkingStalls.filter(s=>s.areaId==='P02'),r=stalls.length?stalls.flatMap(s=>s.ring.slice(0,4)):park?.rings?.[0]?.[0];if(r){const x=r.reduce((s,p)=>s+p[0],0)/r.length,z=r.reduce((s,p)=>s+p[1],0)/r.length;exitWalk(false);state.tour=false;targetMove={target:new THREE.Vector3(x,0,z),position:new THREE.Vector3(x-45,95,z-55)};$('#sidebar').classList.add('hidden');$('#inspector').classList.add('hidden');document.body.classList.remove('inspecting');$('#expand').classList.remove('hidden');resize();updateModes();}return;}if(e.dataset.preset==='gate'){exitWalk(false);const gate=data.gates.find(g=>g.name==='南门');targetMove={target:new THREE.Vector3(...[gate.position[0],7,gate.position[1]-70]),position:new THREE.Vector3(gate.position[0]+90,80,gate.position[1]+100)};state.tour=false;updateModes();}else select(e.dataset.preset,true);});$('#overview').onclick=()=>overview();$('#top').onclick=()=>overview(true);$('#walk').onclick=()=>state.mode==='walk'?exitWalk():enterWalk();$('#tour').onclick=()=>{exitWalk(false);targetMove=null;state.tour=!state.tour;updateModes();};$('#collapse').onclick=()=>{$('#sidebar').classList.add('hidden');$('#expand').classList.remove('hidden');resize();};$('#expand').onclick=()=>{exitWalk(false);$('#sidebar').classList.remove('hidden');$('#expand').classList.add('hidden');resize();};$('#close-inspector').onclick=()=>{$('#inspector').classList.add('hidden');document.body.classList.remove('inspecting');state.selected=null;state.selectedAssemblyId=null;renderList();applyMaterials();};$('#focus').onclick=()=>focusBuilding(data.buildings.find(b=>b.id===state.selected));$('#height-form').onsubmit=e=>{e.preventDefault();const v=Number($('#height-input').value);if(!Number.isFinite(v)||v<2||v>100)return;state.heights[state.selected]=v;updateHeight();toast('已校准展示高度；此数值仍需实测依据');};$('#reset-height').onclick=()=>{delete state.heights[state.selected];updateHeight();toast('已恢复调研参考高度');};function updateHeight(){try{localStorage.setItem('sulit-campus-heights',JSON.stringify(state.heights));}catch{}state.heightVersion++;const b=data.buildings.find(b=>b.id===state.selected),ids=[b.id,...(b.joinedWith||[])];if(b.joinedAssemblyId)for(const id of ids){if(state.heights[b.id]!==undefined)state.heights[id]=state.heights[b.id];else delete state.heights[id];}for(const id of ids){const other=data.buildings.find(x=>x.id===id),g=groups.get(id);if(g)g.scale.y=height(other)/(other.displayHeight||other.estimatedHeight);}try{localStorage.setItem('sulit-campus-heights',JSON.stringify(state.heights));}catch{}select(b.id);}
$('#labels-toggle').onchange=e=>state.labels=e.target.checked;$('#trees-toggle').onchange=e=>{state.trees=e.target.checked;applyMaterials();};$('#white-toggle').onchange=e=>{state.white=e.target.checked;applyMaterials();};$('#gate-select').onchange=e=>{if(!e.target.value)return;focusGate(e.target.value);};$('#reference-close').onclick=()=>$('#reference-dialog').close();$('#review-open').onclick=()=>$('#review-dialog').showModal();$('#review-close').onclick=()=>$('#review-dialog').close();$('#satellite-dialog').close();$('#night').onclick=()=>{state.night=!state.night;if(sky)sky.visible=!state.night;document.body.classList.toggle('night',state.night);$('#night').textContent=state.night?'☀ 日景':'☾ 夜景';scene.background.set(state.night?'#172f34':'#dce7dc');scene.fog.color.copy(scene.background);scene.children.filter(c=>c.isHemisphereLight).forEach(c=>c.intensity=state.night?.3:.8);scene.children.filter(c=>c.isDirectionalLight).forEach(c=>c.intensity=state.night?.45:2.6);applyMaterials();};['#about-btn','#data-info'].forEach(s=>$(s).onclick=()=>$('#about').showModal());$('#close-about').onclick=()=>$('#about').close();$('#screenshot').onclick=()=>{renderScene(true);renderer.domElement.toBlob(blob=>downloadBlob(blob,'苏理工_校园三维视角.png'));toast('正在保存当前三维视角');};$('#download').onclick=async()=>{const b=$('#download');b.disabled=true;b.textContent='正在导出…';try{const buffer=await bytes();if(Object.keys(state.heights).length){const {GLTFExporter}=await import('./vendor/GLTFExporter.js');const gltf=await new GLTFLoader().parseAsync(buffer,'./');gltf.scene.traverse(n=>{if(state.heights[n.userData.id]){const building=data.buildings.find(b=>b.id===n.userData.id);n.scale.y=state.heights[building.id]/(building.displayHeight||building.estimatedHeight);n.userData.userHeightOverride=state.heights[building.id];}});const result=await new GLTFExporter().parseAsync(gltf.scene,{binary:true,onlyVisible:true});downloadBlob(new Blob([result],{type:'model/gltf-binary'}),'苏州理工学院_校园三维_已校准.glb');}else downloadBlob(new Blob([buffer],{type:'model/gltf-binary'}),'苏州理工学院_校园三维_调研版.glb');toast('完整GLB模型已导出');}catch(e){toast('导出失败，请重试或下载对话中的GLB文件');console.error(e);}finally{b.disabled=false;b.textContent='↓ GLB模型';}};
let pointer=null,drag=false;renderer.domElement.addEventListener('pointerdown',e=>{pointer=[e.clientX,e.clientY];drag=false;if(state.mode==='walk')renderer.domElement.setPointerCapture(e.pointerId);});renderer.domElement.addEventListener('pointermove',e=>{if(!pointer)return;if(Math.hypot(e.clientX-pointer[0],e.clientY-pointer[1])>3)drag=true;if(state.mode==='walk'&&e.buttons){walkYaw-=(e.clientX-pointer[0])*.004;walkPitch=Math.max(-1.25,Math.min(1.25,walkPitch-(e.clientY-pointer[1])*.003));pointer=[e.clientX,e.clientY];}});renderer.domElement.addEventListener('pointerup',e=>{if(pointer&&!drag&&state.mode==='orbit')pick(e.clientX,e.clientY);pointer=null;});window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='/'){e.preventDefault();$('#search').focus();return;}if(e.key==='Escape'){exitWalk();$('#about').close();$('#reference-dialog').close();$('#review-dialog').close();$('#satellite-dialog').close();}if(e.key.toLowerCase()==='f'&&state.selected)focusBuilding(data.buildings.find(b=>b.id===state.selected));if(e.code==='Space'){e.preventDefault();$('#tour').click();}keys.add(e.key.toLowerCase());});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());}
function pick(x,y){if(root){const ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2(x/innerWidth*2-1,-y/innerHeight*2+1),camera);for(const hit of ray.intersectObject(root,true)){let n=hit.object;while(n&&!groups.has(n.userData.id))n=n.parent;if(n){select(n.userData.id);return;}}}else{let best=null,depth=Infinity;for(const b of data.buildings){const p=new THREE.Vector3(b.position[0],height(b)/2,b.position[1]).project(camera),sx=(p.x+1)*innerWidth/2,sy=(-p.y+1)*innerHeight/2;const dist=Math.hypot(x-sx,y-sy);if(p.z<1&&dist<Math.max(16,b.lengthApprox*innerHeight/(camera.position.distanceTo(new THREE.Vector3(b.position[0],0,b.position[1])))*.6)&&p.z<depth){best=b;depth=p.z;}}if(best)select(best.id);}}
function labelWorld(b){const a=b.labelAnchor;return a?[a.position[0],height(b)*a.heightRatio,a.position[1]]:[b.position[0],height(b)+3,b.position[1]];}
function labelOccluded(b){const to=labelWorld(b),from=[camera.position.x,camera.position.y,camera.position.z],dx=to[0]-from[0],dz=to[2]-from[2];for(const other of data.buildings){if(other.id===b.id||other.type==='context_reference')continue;const r=other.rings[0],H=height(other)+.7;for(let i=1;i<r.length;i++){const a=r[i-1],c=r[i],ex=c[0]-a[0],ez=c[1]-a[1],det=dx*ez-dz*ex;if(Math.abs(det)<1e-8)continue;const ax=a[0]-from[0],az=a[1]-from[2],t=(ax*ez-az*ex)/det,u=(ax*dz-az*dx)/det;if(t<=.001||t>=.999||u<0||u>1)continue;const y=from[1]+t*(to[1]-from[1]);if(y>.05&&y<H)return true;}}return false;}
function updateLabels(){const used=[];for(const l of [...labels].sort((a,b)=>(state.selected===a.b.id?-1:state.selected===b.b.id?1:Math.hypot(a.b.position[0]-camera.position.x,a.b.position[1]-camera.position.z)-Math.hypot(b.b.position[0]-camera.position.x,b.b.position[1]-camera.position.z)))){const p=new THREE.Vector3(...labelWorld(l.b)).project(camera),x=(p.x+1)*innerWidth/2,y=(-p.y+1)*innerHeight/2,selected=state.selected===l.b.id,labelWidth=l.el.textContent.length*8+16;let show=state.labels&&state.mode!=='walk'&&p.z<1&&p.z>-1&&x>15&&x<innerWidth-20&&y>85&&y<innerHeight-90;if(innerWidth>760&&!$('#sidebar').classList.contains('hidden')&&x<320)show=false;if(!['ancillary','context_reference'].includes(l.b.type)||selected){if(!selected&&used.some(q=>Math.abs(q[0]-x)<(q[2]+labelWidth)/2+8&&Math.abs(q[1]-y)<30))show=false;}else show=false;if(show&&!selected&&labelOccluded(l.b))show=false;if(show){used.push([x,y,labelWidth]);l.el.style.left=x+'px';l.el.style.top=y+'px';l.el.classList.toggle('selected',selected);}l.el.style.display=show?'block':'none';}}
function bridgeGrade(x,z){for(const b of data.hydroNetwork.bridges){const dx=x-b.center[0],dz=z-b.center[1],u=dx*b.axis[0]+dz*b.axis[1],v=-dx*b.axis[1]+dz*b.axis[0];if(Math.abs(u)<=b.span/2&&Math.abs(v)<=b.width/2)return .18+(b.id==='BR15'?.95:0)*Math.max(0,1-(u/(b.span/2))**2);}return 0;}
function animate(t){const dt=Math.min((t-last)/1000,renderer.isSoftwareRenderer?.25:.06);last=t;if(state.mode==='walk'){let dx=0,dz=0,speed=(keys.has('shift')?12:4.2)*dt;if(keys.has('w')||keys.has('arrowup'))dz-=speed;if(keys.has('s')||keys.has('arrowdown'))dz+=speed;if(keys.has('a')||keys.has('arrowleft'))dx-=speed;if(keys.has('d')||keys.has('arrowright'))dx+=speed;const mx=dx*Math.cos(walkYaw)+dz*Math.sin(walkYaw),mz=-dx*Math.sin(walkYaw)+dz*Math.cos(walkYaw);if(canWalk(camera.position.x+mx,camera.position.z))camera.position.x+=mx;if(canWalk(camera.position.x,camera.position.z+mz))camera.position.z+=mz;camera.position.y=1.78+bridgeGrade(camera.position.x,camera.position.z);camera.lookAt(camera.position.x-Math.sin(walkYaw)*10,camera.position.y+Math.sin(walkPitch)*10,camera.position.z-Math.cos(walkYaw)*10);}else{if(targetMove){const a=1-Math.exp(-dt*4);camera.position.lerp(targetMove.position,a);controls.target.lerp(targetMove.target,a);if(camera.position.distanceTo(targetMove.position)<.15)targetMove=null;}if(state.tour){const a=dt*.07,p=camera.position.clone().sub(controls.target);p.applyAxisAngle(new THREE.Vector3(0,1,0),a);camera.position.copy(controls.target).add(p);}controls.update();}camera.updateMatrixWorld();renderScene();updateLabels();requestAnimationFrame(animate);}
function renderScene(force=false){if(renderer.isSoftwareRenderer){renderer.render(scene,camera);return;}const signature=camera.matrixWorld.elements.map(x=>x.toFixed(7)).join(',')+camera.projectionMatrix.elements.map(x=>x.toFixed(6)).join(',')+JSON.stringify([state.selected,state.night,state.white,state.trees,state.water,state.heightVersion,state.quality,innerWidth,innerHeight]);if(!force&&signature===renderSignature)return;renderSignature=signature;if(composer&&state.quality){try{composer.render();}catch(e){console.error(e);composer=null;renderer.render(scene,camera);}}else renderer.render(scene,camera);}
function showReferences(b){const refs=(b.referenceIds||[]).map(id=>data.references?.[id]).filter(Boolean);$('#reference-section').classList.toggle('hidden',!refs.length);$('#reference-images').replaceChildren(...refs.map(ref=>{const button=document.createElement('button'),img=document.createElement('img');img.src=ref.image;img.alt=ref.caption;img.loading='lazy';button.append(img);button.title=ref.caption;button.onclick=()=>{$('#reference-large').src=ref.image;$('#reference-large').alt=ref.caption;$('#reference-caption').textContent=ref.caption;$('#reference-source').href=ref.url;$('#reference-dialog').showModal();};return button;}));}
function focusGate(name){const gate=data.gates.find(g=>g.name===name);if(!gate)return;exitWalk(false);const [nx,nz]=gate.outwardAxis,lib=data.buildings.find(b=>b.id==='B01');targetMove={target:new THREE.Vector3(name==='南门'?lib.position[0]*.12+gate.position[0]*.88:gate.position[0],name==='南门'?8:3.5,name==='南门'?lib.position[1]*.12+gate.position[1]*.88:gate.position[1]),position:new THREE.Vector3(gate.position[0]+nx*105,name==='南门'?24:48,gate.position[1]+nz*105)};state.tour=false;updateModes();toast(name==='南门'?'南门：沿图书馆主轴查看入口':name==='东门'?'东门：校园侧桥头 · 引道与校门共轴':name+'：伸缩门已完全关闭');}

function buildReview(){const table=document.createElement('table');table.innerHTML='<thead><tr><th>建筑</th><th>形态依据</th><th>细部与尺寸</th></tr></thead>';const body=document.createElement('tbody');for(const b of data.buildings){const row=document.createElement('tr');for(const value of [b.id+' '+b.name,b.reviewStatus,b.uncertainFields.slice(0,3).join('；')]){const td=document.createElement('td');td.textContent=value;row.append(td);}body.append(row);}table.append(body);$('#review-table').replaceChildren(table);}
init().catch(e=>{console.error(e);if($('#loading-text'))$('#loading-text').textContent='布局下载中断，请重试或使用备用入口。';if($('#progress'))$('#progress').style.background='#b77c4f';$('#load-retry').hidden=false;});
